package com.plexus.personal.document.application;
import com.plexus.personal.document.infrastructure.*; import org.springframework.stereotype.Service; import java.util.*;
@Service public class KnowledgeSearchService {private final DocumentChunkMapper mapper; private final EmbeddingService embeddings; public KnowledgeSearchService(DocumentChunkMapper m,EmbeddingService e){mapper=m;embeddings=e;} public List<Map<String,Object>> search(Long userId,String query,int limit){double[] q=parse(embeddings.embed(query));return mapper.findByUserId(userId).stream().map(c->Map.entry(c,cosine(q,parse(c.embedding)))).filter(e->e.getValue()>0).sorted((a,b)->Double.compare(b.getValue(),a.getValue())).limit(limit).map(e->{Map<String,Object> m=new LinkedHashMap<>();m.put("chunk_id",e.getKey().id);m.put("document_id",e.getKey().documentId);m.put("source",e.getKey().sourceFilename);m.put("content",e.getKey().content);m.put("score",e.getValue());return m;}).toList();} private double[] parse(String s){if(s==null||s.length()<3)return new double[0];String[] a=s.substring(1,s.length()-1).split(", ");double[] v=new double[a.length];for(int i=0;i<a.length;i++)v[i]=Double.parseDouble(a[i]);return v;}private double cosine(double[] a,double[] b){double x=0;for(int i=0;i<Math.min(a.length,b.length);i++)x+=a[i]*b[i];return x;}}
